 需求文档：https://moonton.feishu.cn/docx/doxcnWZLNIr8YvU46VVlzHab3dg
 */ /*  数据从2019-06-21开始 */ /* WITH config AS ( */ /*     SELECT  app_original_name, */ /*             app_config_name */ /*     FROM    mt_dim.dim_competitor_appname_config_mlbb */ /*     WHERE logymd = '2026-05-31' */ /*     GROUP BY */ /*             app_original_name, */ /*             app_config_name */ /* ), */ /* app_all AS ( */ /*     SELECT  accountid, */ /*             app_original_name, */ /*             app_config_name, */ /*             app_type */ /*     FROM    mt_dwd.dwd_competitor_account_di */ /*     WHERE   logymd = '2026-05-31' and appid = 'mlbb' */ /* ), */ /* app_all_config AS ( */ /*     SELECT */ /*             app_all.accountid, */ /*             app_all.app_original_name, */ /*             app_all.app_type, */ /*             config.app_config_name */ /*     FROM    app_all */ /*     INNER JOIN */ /*             config */ /*     -- ON      app_all.app_original_name = config.app_original_name */ /*     ON      lower(trim(app_all.app_config_name)) = lower(trim(config.app_original_name)) -- 修改时间：2023-07-10 */ /* ), */ WITH app_all_config AS (SELECT accountid, app_original_name, app_config_name, app_type FROM mt_dwd.dwd_competitor_account_di WHERE logymd = '2026-05-31' AND appid = 'mlbb'), competitor AS (SELECT accountid, app_original_name, app_config_name, app_type, app_first_install_ymd FROM mt_dwm.dwm_competitor_account_df WHERE logymd = '2026-05-30'), left_competitor AS (SELECT accountid, app_original_name, app_config_name, app_type, '2026-05-31' AS app_first_install_ymd FROM app_all_config AS a WHERE NOT EXISTS(SELECT accountid, app_original_name, app_config_name, app_type, app_first_install_ymd FROM competitor AS b WHERE a.accountid = b.accountid AND a.app_original_name = b.app_original_name AND a.app_type = b.app_type)) INSERT OVERWRITE TABLE mt_dwm.dwm_competitor_account_df PARTITION(logymd = '2026-05-31', appid = 'mlbb') SELECT accountid, app_original_name, app_config_name, app_type, app_first_install_ymd FROM (SELECT accountid, app_original_name, app_config_name, app_type, app_first_install_ymd FROM competitor UNION ALL SELECT accountid, app_original_name, app_config_name, app_type, app_first_install_ymd FROM left_competitor)

/*
同步mla中间表：mh_ods.returning_user_detail
*/ INSERT OVERWRITE TABLE mt_dwd.dwd_returning_user_detail_mla PARTITION(logymd = '2026-05-31') SELECT time, roleid, zoneid, os_type, usercreateymd, activedays, chargecou, level, vip, alliance_id, device, floor_tier, channel, client_ip, lag_ymd FROM (SELECT time, roleid, zoneid, os_type, usercreateymd, activedays, chargecou, level, vip, alliance_id, device, floor_tier, channel, client_ip, logymd, LAG(logymd, 1, NULL) OVER (PARTITION BY roleid, zoneid ORDER BY logymd) AS lag_ymd FROM (SELECT time, roleid, zoneid, os_type, usercreateymd, activedays, chargecou, level, vip, alliance_id, device, floor_tier, channel, ip AS client_ip, logymd, ROW_NUMBER() OVER (PARTITION BY roleid, zoneid, logymd, usercreateymd ORDER BY time) AS rowid FROM mh_ods.gameserver_login WHERE logymd BETWEEN '2026-03-03' AND '2026-05-31' AND (zoneid DIV 1000) <> 9 AND reconn = 0) AS a WHERE rowid = 1) AS t WHERE logymd = '2026-05-31' GROUP BY time, roleid, zoneid, os_type, usercreateymd, activedays, chargecou, level, vip, alliance_id, device, floor_tier, channel, client_ip, lag_ymd, logymd HAVING DATEDIFF(logymd, COALESCE(t.lag_ymd, t.usercreateymd)) >= 7

/* set spark.sql.autoBroadcastJoinThreshold=-1; */ /* set spark.sql.adaptive.skewJoin.skewedPartitionFactor=3; */ /* set spark.sql.adaptive.skewedPartitionMaxSplits=10; */ /* set spark.sql.adaptive.skewedPartitionRowCountThreshold=1000; */ /* set spark.sql.adaptive.skewedPartitionSizeThreshold=2048000; */ /* set spark.sql.adaptive.skewJoin.enabled=false; */ INSERT OVERWRITE TABLE mt_dwd.dwd_tqs_query_detail_di PARTITION(logymd = '2026-05-31') SELECT id, task_id, project_name, application_id, queuename, engine_type, user_name AS user_email, user_name_ch AS user_name, department AS dp_name, status, start_time, end_time, duration, schedule_type, query, trigger_type, trigger_type_ch, instance_id, task_date /* 任务实例业务日期 */, external_sub_application_id, trigger_id, tqs_id, task_type, task_type_name FROM (SELECT id, engine_type, user_name, status, FROM_UNIXTIME(start_time + 8 * 3600) AS start_time, FROM_UNIXTIME(end_time + 8 * 3600) AS end_time, COALESCE((end_time - start_time), -1) AS duration, IF(`conf` LIKE '%dorado.task.version%-1%', 1, 0) AS schedule_type /* 调度类型：1是临时查询，0是日常调度 */, SPLIT(name, '_')[2] AS task_id, STR_TO_MAP(REGEXP_REPLACE(conf, '\{|\}|"', ''), ',', ':')['mapreduce.job.queuename'] AS queuename, query /* 替换存储的ad-hoc查询中
