]+|[	]+|[\s]+', ' ')) AS sql --presto    */ FROM (SELECT id, CONCAT(id, '_spark2') AS tqs_id, app_id, assign_engine_id, engine_type, user_name, query, status, cost, max_results, log_url, start_time, end_time, `conf`, progress, name, date, REGEXP_EXTRACT(GET_JSON_OBJECT(progress, '$.trackingUrl'), 'application_([0-9]+_[0-9]+)', 0) AS application_id FROM mt_ods.dl_tqs__tqs_query_task_df WHERE date = IF('20260531' < '20220608', '20220608', '20260531') AND FROM_UNIXTIME(start_time + 8 * 3600, 'yyyy-MM-dd') = '2026-05-31' /* and name not like '%dp_dts_tqs_query%' --过滤掉数据集成任务 */ UNION ALL SELECT id, CONCAT(id, '_spark3') AS tqs_id, app_id, assign_engine_id, engine_type, user_name, query, status, cost, max_results, log_url, start_time, end_time, `conf`, progress, name, date, IF(engine_type = 'Presto', REPLACE(GET_JSON_OBJECT(progress, '$.trackingUrl'), 'http://presto-history.byted.org/proxy/', ''), REGEXP_EXTRACT(GET_JSON_OBJECT(progress, '$.trackingUrl'), 'application_([0-9]+_[0-9]+)', 0)) AS application_id FROM mt_ods.dl_tqs_spark3__tqs_query_task_df WHERE date = IF('20260531' < '20220914', '20220914', '20260531') AND FROM_UNIXTIME(start_time + 8 * 3600, 'yyyy-MM-dd') = '2026-05-31') AS a LEFT JOIN (SELECT t.id AS task_id, a.name AS project_name, t.type AS task_type, CASE WHEN t.type = 202 THEN 'Shell' WHEN t.type = 203 THEN 'Python' WHEN t.type = 201 THEN 'HSQL' WHEN t.type = 402 THEN 'hive-sensor' WHEN t.type = 403 THEN 'hdfs-sensor' WHEN t.type = 701 THEN 'spark' WHEN t.type = 901 THEN 'notebook' WHEN t.type LIKE '%10%' THEN 'dts' /* 离线集成任务 */ END AS task_type_name FROM mt_ods.dl_dorado__project_df AS a LEFT JOIN mt_ods.dl_dorado__folder_df AS b ON a.id = b.project_id JOIN mt_ods.dl_dorado__task_df AS t ON b.id = t.folder_id WHERE a.`date` = '20260531' AND b.`date` = '20260531' AND t.`date` = '20260531' GROUP BY t.id, a.name, t.type, CASE WHEN t.type = 202 THEN 'Shell' WHEN t.type = 203 THEN 'Python' WHEN t.type = 201 THEN 'HSQL' WHEN t.type = 402 THEN 'hive-sensor' WHEN t.type = 403 THEN 'hdfs-sensor' WHEN t.type = 701 THEN 'spark' WHEN t.type = 901 THEN 'notebook' WHEN t.type LIKE '%10%' THEN 'dts' /* 离线集成任务 */ END) AS b ON SPLIT(a.name, '_')[2] = b.task_id LEFT JOIN (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY instance_id ORDER BY update_time DESC) AS rn FROM (SELECT SPLIT(REPLACE(external_sub_application_id, 'etl_', ''), '-')[0] AS tqs_id, a.id AS instance_id, a.task_id, a.external_sub_application_id, b.id AS trigger_id, b.type AS trigger_type, FROM_UNIXTIME(a.task_time + 8 * 3600) AS task_date, a.update_time, b.trigger_type_ch FROM mt_ods.dl_dorado__instance_hi AS a LEFT JOIN (SELECT id, type, CASE WHEN type = 1 THEN '系统调度' WHEN type = 2 THEN '手动调度' WHEN type = 10 THEN '重跑' WHEN type = 11 THEN '回溯下游' WHEN type = 13 THEN '调试' WHEN type = 14 THEN '临时查询' ELSE '其他' END AS trigger_type_ch FROM mt_ods.dl_dorado__instance_trigger_df WHERE date = '20260531') AS b ON a.trigger_id = b.id WHERE a.date BETWEEN '20260531' AND '20260601' /* 小时任务，允许跨天5h */ AND NOT external_sub_application_id IS NULL) AS ti) WHERE rn = 1) AS c ON a.id = c.tqs_id LEFT JOIN (SELECT * FROM (SELECT email, dp_name AS department, user_name AS user_name_ch, ROW_NUMBER() OVER (PARTITION BY email ORDER BY logymd DESC) AS rn FROM mt_dim.dim_mt_user_info WHERE logymd <= IF('2026-05-30' <= '2025-11-20', '2025-11-20', '2026-05-30')) AS t WHERE rn = 1) AS u ON a.user_name = u.email) AS a /* -- ******************************************************************** */ /* -- Author: fuxinwang@moonton.com */ /* -- Create by: 2022-06-17 11:18:32.000 */ /* -- Description: */ /* -- Update: Task Update Description */ /* -- ******************************************************************** */ /* -- create external table if not exists mt_dwd.dwd_tqs_query_detail_di ( */ /* --     `id` bigint COMMENT 'id', */ /* --     `task_id` bigint COMMENT '任务ID', */ /* --     `project_name` string COMMENT '项目名称', */ /* --      application_id string comment 'yarn appid', */ /* --     `queuename` string COMMENT '队列', */ /* --     `engine_type` string COMMENT 'engine_type', */ /* --     `user_email` string COMMENT '用户邮箱', */ /* --     `user_name` string COMMENT 'user_name', */ /* --     -- `is_da` int COMMENT '是否是DA', */ /* --     -- `fallback` string COMMENT '是否回退spark', */ /* --     -- `ddl` string COMMENT '是否建表语句', */ /* --     `status` string COMMENT 'status', */ /* --     `start_time` string COMMENT 'start_time', */ /* --     `end_time` string COMMENT 'end_time', */ /* --     `duration` int COMMENT '耗时', */ /* --     `task_type` string COMMENT '任务类型,1是临时查询', */ /* --     `query` string COMMENT '原始sql', */ /* --     -- `sql` string COMMENT '处理后sql', */ /* --     -- `sql_str` string COMMENT '分段sql', */ /* --     -- `table_name` string COMMENT '表名', */ /* --     -- `is_table` string COMMENT '是否正常表名', */ /* --     `trigger_type` bigint COMMENT '实例触发类型', */ /* --      trigger_type_ch string comment '实例触发类型-中文', */ /* --     `instance_id` bigint COMMENT '实例id', */ /* --     `task_date` string COMMENT '业务日期', */ /* --     `external_sub_application_id` string COMMENT '外部任务 ID（如 yarn application ID，TCE pod ID）', */ /* --     `trigger_id` bigint COMMENT '触发器id', */ /* --      tqs_id  string comment '查询id' */ /* -- ) partitioned by (logymd string comment '分区') */ /* -- stored as parquet; */ /* -- create table if not exists mt_dwd.dwd_leap_spark_query_info_di ( */ /* --      yarn_application_id string comment 'yarn appid', */ /* --      table_name string comment '查询表名', */ /* --      column_name  string comment '字段名' */ /* -- ) partitioned by (logymd string comment '分区') */ /* -- stored as parquet */ /* -- location 's3a://mt-dwd/table/dwd_leap_spark_query_info_di' ; */ /* -- SET spark.sql.hive.optimize.sort.dynamic.partition=true; */ /* -- set spark.hadoop.hive.exec.dynamic.partition.mode=nonstrict; */ /* -- SET spark.hadoop.hive.exec.max.dynamic.partitions=1800; */ /* set spark.sql.hive.convertMetastoreParquet=true; */ /* -- set spark.sql.hive.conve