nRowCountThreshold=1000; */ /* set spark.sql.adaptive.skewedPartitionSizeThreshold=2048000; */ /* -- set spark.sql.adaptive.skewJoin.enabled=false; */ /* INSERT OVERWRITE TABLE mt_dwd.dwd_tqs_query_detail_di PARTITION (logymd = '2026-05-31') */ /* select / *+ repartition(20) * / */ /*   id */ /*  ,task_id */ /*  ,project_name */ /*  ,application_id */ /*  ,queuename */ /*  ,engine_type */ /*  ,user_name as user_email */ /*  ,user_name_ch as user_name */ /*  ,status */ /*  ,start_time */ /*  ,end_time */ /*  ,duration */ /*  ,task_type */ /*  ,query */ /*  ,trigger_type */ /*  ,trigger_type_ch */ /*  ,instance_id */ /*  ,task_date --任务实例业务日期 */ /*  ,external_sub_application_id */ /*  ,trigger_id */ /*  ,tqs_id */ /* from( */ /*     SELECT */ /*             id , */ /*             engine_type, */ /*             user_name, */ /*             IF(execution_info LIKE '%fallbackType%Presto%', 'fallback', 'nofallback') as fallback, */ /*             -- if(lower(`query`) LIKE '%create % table%','create query','select') as ddl, */ /*             status, */ /*             from_unixtime(start_time+8*3600,'yyyy-MM-dd HH:mm:ss') AS start_time, */ /*             from_unixtime(end_time+8*3600,'yyyy-MM-dd HH:mm:ss') AS end_time, */ /*             nvl((end_time - start_time),-1) AS duration, */ /*             if(`conf` LIKE '%dorado.task.version%-1%',1,0) as task_type, */ /*             split(name,'_')[2] as task_id, */ /*             str_to_map(regexp_replace(conf,'\{|\}|"',''),',',':')['mapreduce.job.queuename'] as queuename, */ /*             --替换存储的ad-hoc查询中
