 SELECT  *, */ /*                                 row_number() OVER (PARTITION BY instance_id ORDER BY update_time DESC) AS rn */ /*                         FROM    ( */ /*                                     SELECT  split(replace(external_sub_application_id, 'etl_', ''), '-')[0] AS tqs_id, */ /*                                             a.id AS instance_id, */ /*                                             a.task_id, */ /*                                             a.external_sub_application_id, */ /*                                             b.id AS trigger_id, */ /*                                             b.type AS trigger_type, */ /*                                             FROM_UNIXTIME(a.task_time + 8 * 3600, 'yyyy-MM-dd HH:mm:ss') AS task_date, */ /*                                             a.update_time, */ /*                                             b.trigger_type_ch */ /*                                     FROM    mt_ods.dl_dorado__instance_hi a */ /*                                     LEFT JOIN */ /*                                             ( */ /*                                                 SELECT  id, */ /*                                                         type, */ /*                                                         case */ /*                                                         when type = 1 then '系统调度' */ /*                                                         when type = 2 then '手动调度' */ /*                                                         when type = 10 then '重跑' */ /*                                                         when type = 11 then '回溯下游' */ /*                                                         when type = 13 then '调试' */ /*                                                         when type = 14 then '临时查询' */ /*                                                         else '其他' */ /*                                                         end as trigger_type_ch */ /*                